const fs = require('fs');

// Count existing photos
let photoCount = 0;
let photoCountWarning = '';
try {
  const dir = '/var/lib/nixframe/photos';
  const files = fs.readdirSync(dir);
  photoCount = files.filter(f => /\.(jpg|jpeg|png|webp)$/i.test(f) && !f.startsWith('.')).length;
} catch (e) {
  if (e.code !== 'ENOENT') {
    photoCountWarning = 'Nu am putut număra pozele din ramă';
    console.error('Failed to list photo directory:', e.message);
  }
}
