  <button class="btn" id="submitBtn" disabled>Trimite în ramă</button>
  <div class="result" id="result" role="status" aria-live="polite"></div>
</main>
<script>
const MAX = 12 * 1024 * 1024, OK_TYPES = ['image/jpeg','image/png','image/webp','image/heic','image/heif'];
const EXT_MIME = { jpg:'image/jpeg', jpeg:'image/jpeg', png:'image/png', webp:'image/webp', heic:'image/heic', heif:'image/heif' };
function mimeOf(file) {
  if (OK_TYPES.includes(file.type)) return file.type;
  const ext = (file.name.split('.').pop() || '').toLowerCase(), m = EXT_MIME[ext];
  if (!m) return null;
  return (!file.type || file.type === 'application/octet-stream' || ext === 'heic' || ext === 'heif') ? m : null;
}
const $ = id => document.getElementById(id);
const dropZone=$('dropZone'), fileInput=$('fileInput'), previewsEl=$('previews'), submitBtn=$('submitBtn'), bar=$('progressBar'), fill=$('progressFill'), ptext=$('progressText'), result=$('result');
let files = [], busy = false, stackUrls = [];
