const liveUrls = new Set();
function gc() { const keep = new Set(files.map(f => f.url).concat(stackUrls)); for (const u of liveUrls) if (!keep.has(u)) { URL.revokeObjectURL(u); liveUrls.delete(u); } }
const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
