fileInput.addEventListener('change', e => { add(e.target.files); fileInput.value = ''; });
function add(list) {
  if (busy) return;
  files = files.filter(f => f.status !== 'done');
  const skipped = [];
  for (const file of list) {
    if (!mimeOf(file)) { skipped.push(file.name + ' nu e o poză pe care rama o poate arăta'); continue; }
    if (file.size > MAX) { skipped.push(file.name + ' e prea mare (' + Math.round(file.size/1048576) + ' MB; maximum 12 MB)'); continue; }
    const url = URL.createObjectURL(file); liveUrls.add(url);
    files.push({ file, mime: mimeOf(file), url, status: 'pending' });
  }
  result.className = 'result'; stackUrls = [];
  if (skipped.length) { result.className = 'result partial'; result.innerHTML = '<h2>Câteva poze au rămas pe dinafară</h2><p>' + skipped.map(esc).join('<br>') + '</p>'; }
  gc(); render(); ui();
}
function render() {
  previewsEl.innerHTML = '';
  files.forEach((f, i) => {
    const d = document.createElement('div'); d.className = 'preview-item';
    const img = document.createElement('img'); img.src = f.url; img.alt = '';
    img.onerror = () => { img.remove(); const fb = document.createElement('div'); fb.className = 'fallback'; fb.textContent = 'Poză (fără previzualizare)'; d.prepend(fb); };
    d.appendChild(img);
    if (!busy && f.status !== 'done' && f.status !== 'uploading') {
      const b = document.createElement('button'); b.className = 'remove'; b.setAttribute('aria-label', 'Scoate poza ' + (i + 1));
      b.innerHTML = '<span aria-hidden="true">×</span>'; b.onclick = () => { files.splice(i, 1); gc(); render(); ui(); }; d.appendChild(b);
    }
    if (f.status !== 'pending') { const s = document.createElement('div'); s.className = 'status-badge ' + f.status; s.textContent = f.status === 'uploading' ? 'Se trimite…' : f.status === 'done' ? 'În ramă' : 'N-a mers'; d.appendChild(s); }
    previewsEl.appendChild(d);
  });
}
function ui() {
  const todo = files.filter(f => f.status === 'pending' || f.status === 'fail').length;
  const retry = files.some(f => f.status === 'fail');
  submitBtn.disabled = busy || todo === 0;
  submitBtn.textContent = busy ? 'Se trimite…' : todo === 0 ? 'Trimite în ramă' : (retry ? 'Încearcă din nou (' + poze(todo) + ')' : 'Trimite ' + poze(todo) + ' în ramă');
}
function readB64(file) { return new Promise((ok, no) => { const r = new FileReader(); r.onload = () => ok(r.result); r.onerror = () => no(r.error); r.readAsDataURL(file); }); }
// Messages the upload handler sends in "error" (Validate and Save, MSG_*): already written for her, shown as they are.
const SERVER_MSGS = [
  'Formatul pozei nu e acceptat. Folosește JPG, PNG, WebP sau HEIC.',
  'Poza e prea mare.',
  'Poza a durat prea mult. Încearcă una mai mică.',
  'Rama nu a putut citi formatul acestei poze. Încearcă altă poză.',
  'Poza nu a putut fi salvată. Încearcă din nou.',
];
function friendly(err, status) {
  if (SERVER_MSGS.includes(err)) return err;
  if (status === 413) return 'poza e prea mare pentru ramă. Încearcă una mai mică.';
  if (status) return 'rama nu a răspuns cum trebuie. Mai încearcă peste un minut.';
  if (err === 'timeout') return 'a durat prea mult. Verifică internetul și încearcă din nou.';
  if (err === 'network') return 'nu am putut ajunge la ramă. Verifică dacă Tailscale e pornit pe telefon și încearcă din nou.';
  if (/prea mare|too large/i.test(err)) return friendly('', 413);
  if (/format|process|convert/i.test(err)) return 'rama nu poate citi formatul acestei poze. Încearcă altă poză.';
  return 'ceva n-a mers. Încearcă din nou.';
}
submitBtn.addEventListener('click', async () => {
  const queue = files.filter(f => f.status === 'pending' || f.status === 'fail');
  if (!queue.length || busy) return;
  busy = true; result.className = 'result'; bar.style.display = 'block'; render(); ui();
  const failed = [], saved = [];
  for (let i = 0; i < queue.length; i++) {
    const f = queue[i]; f.status = 'uploading'; render();
    ptext.textContent = 'Trimit poza ' + (i + 1) + ' din ' + queue.length + '…';
    fill.style.width = (i / queue.length * 100) + '%';
    let why = null;
    try {
      const data = (await readB64(f.file)).replace(/^data:[^;,]*/, 'data:' + f.mime);
      const ctl = new AbortController(); const t = setTimeout(() => ctl.abort(), 60000);
      let r;
      try { r = await fetch('/webhook/nixframe-upload', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ imageData: data }), signal: ctl.signal }); }
      catch (e) { why = friendly(e.name === 'AbortError' ? 'timeout' : 'network'); }
      finally { clearTimeout(t); }
      if (!why && !r.ok) { const j = r.status === 413 ? null : await r.json().catch(() => null); why = j && j.error ? friendly(j.error) : friendly('', r.status); }
      if (!why) { const j = await r.json().catch(() => ({})); if (!j.success) why = friendly(j.error || ''); }
    } catch (e) { why = friendly('read'); }
    if (why) { f.status = 'fail'; failed.push('Poza ' + (files.indexOf(f) + 1) + ': ' + why); } else { f.status = 'done'; saved.push(f); }
    render(); fill.style.width = ((i + 1) / queue.length * 100) + '%';
  }
  busy = false; ptext.textContent = ''; bar.style.display = 'none'; fill.style.width = '0%';
  if (saved.length) { const c = document.querySelector('.photo-count'); const m = c.textContent.match(/(\\d+)/); if (m) c.textContent = poze(+m[1] + saved.length) + " în ramă"; }
  stackUrls = saved.slice(-5).map(f => f.url);
  const stack = saved.length ? '<div class="stack">' + saved.slice(-5).map(f => '<img alt="" src="' + f.url + '">').join('') + '</div>' : '';
  const when = '<p>Apar pe televizor pe rând, câte una pe minut, printre celelalte.</p>';
  if (!failed.length) { result.className = 'result success'; result.innerHTML = stack + '<h2>Gata! ' + (saved.length === 1 ? 'Poza a ajuns' : 'Pozele au ajuns') + ' în ramă.</h2>' + when;
    files = files.filter(f => f.status !== 'done'); }
  else if (!saved.length) { result.className = 'result error'; result.innerHTML = '<h2>' + (failed.length === 1 ? 'Poza nu a ajuns' : 'Pozele nu au ajuns') + ' în ramă</h2><p>' + failed.map(esc).join('<br>') + '</p>'; }
  else { result.className = 'result partial'; result.innerHTML = stack + '<h2>' + poze(saved.length) + ' în ramă, ' + poze(failed.length) + ' nu</h2><p>' + failed.map(esc).join('<br>') + '</p><p>Apasă „Încearcă din nou" doar pentru cele care n-au mers.</p>'; }
  gc(); render(); ui();
});
</script>
</body>
</html>
`;

